using System;using System.IO;using System.Text;using System.Threading;using System.Windows.Forms;
namespace DjiMicKey {
    sealed class PowerWatchForm:Form {
        readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer();readonly InputTrace trace=new InputTrace();KeyboardMapper mapper;RawControlTrace raw;readonly string report;readonly int seconds;readonly DateTime started=DateTime.UtcNow;
        public PowerWatchForm(string path,int duration){report=Path.GetFullPath(path);seconds=Math.Max(15,Math.Min(120,duration));ShowInTaskbar=false;WindowState=FormWindowState.Minimized;FormBorderStyle=FormBorderStyle.FixedToolWindow;Opacity=0.01;Text="DJI button diagnostic";timer.Interval=200;timer.Tick+=Tick;}
        protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);try{trace.Start();trace.Add("START "+InputTrace.EnvironmentReport().Replace(Environment.NewLine," | "));mapper=new KeyboardMapper();mapper.Enabled=false;mapper.Connected=true;mapper.Trace=trace;trace.Add("HOOK running="+mapper.IsRunning+" health="+mapper.ProbeHealth());raw=new RawControlTrace(trace);trace.Add("RAW registration ready");timer.Start();}catch(Exception ex){trace.Add("START ERROR "+Native.Error(ex));Finish();}}
        void Tick(object sender,EventArgs args){if((DateTime.UtcNow-started).TotalSeconds>=seconds){trace.Add("TIME LIMIT seconds="+seconds);Finish();}}
        void Finish(){timer.Stop();trace.Add("END");if(raw!=null){raw.Dispose();raw=null;}if(mapper!=null){mapper.Dispose();mapper=null;}try{Directory.CreateDirectory(Path.GetDirectoryName(report));File.WriteAllText(report,"DJI Mic Key power-button diagnostic v"+typeof(Program).Assembly.GetName().Version+Environment.NewLine+"Duration: "+(DateTime.UtcNow-started).TotalSeconds.ToString("0.0")+" sec"+Environment.NewLine+trace.Stop(),Encoding.UTF8);}finally{Close();Application.ExitThread();}}
        protected override void WndProc(ref Message message){if(message.Msg==0xFF&&trace.Active){uint size=0,header=(uint)(8+2*IntPtr.Size);Native.GetRawInputData(message.LParam,0x10000003,IntPtr.Zero,ref size,header);if(size>header&&size<65536){IntPtr data=System.Runtime.InteropServices.Marshal.AllocHGlobal((int)size);try{if(Native.GetRawInputData(message.LParam,0x10000003,data,ref size,header)!=UInt32.MaxValue){IntPtr device=System.Runtime.InteropServices.Marshal.ReadIntPtr(data,8);if(raw!=null&&raw.IsDjiSource(device)){uint kind=(uint)System.Runtime.InteropServices.Marshal.ReadInt32(data);if(kind==2){byte[] bytes=new byte[Math.Min(32,(int)size-(int)header)];System.Runtime.InteropServices.Marshal.Copy(IntPtr.Add(data,(int)header),bytes,0,bytes.Length);trace.Add("RAW DJI bytes="+BitConverter.ToString(bytes));}else if(kind==1)trace.Add("RAW DJI keyboard vk="+System.Runtime.InteropServices.Marshal.ReadInt16(data,(int)header+6).ToString("X"));}}}finally{System.Runtime.InteropServices.Marshal.FreeHGlobal(data);}}}base.WndProc(ref message);}
        protected override void Dispose(bool disposing){if(disposing){timer.Dispose();if(raw!=null)raw.Dispose();if(mapper!=null)mapper.Dispose();}base.Dispose(disposing);}
    }
    static class PowerWatch {public static int Run(string[] args){if(args.Length<2)return 2;int seconds=45;if(args.Length>2)Int32.TryParse(args[2],out seconds);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{Application.Run(new PowerWatchForm(args[1],seconds));return File.Exists(args[1])?0:1;}catch(Exception ex){File.WriteAllText(args[1],"Power-watch failed: "+ex);return 1;}}}
}
